      ],
      "source_documents": [
        "beyond_capitalism_2"
      ],
      "representative_quotes": [
        {
          "source_work_title": "Beyond Capitalism—2",
          "source_locator": "Section 7",
          "quote": "Instead of abolishing professionalization, it must be universalized: everyone could be an expert in something."
        },
        {
          "source_work_title": "Beyond Capitalism—2",
          "source_locator": "Section 7",
          "quote": "A society that values teaching or care work, for example, may choose to raise salaries for those professions even if their rental charges remain relatively low."
        }
      ],
      "centrality": "major"
