    }
  ],
  "themes": [
    {
      "theme_name": "Calculation in Kind and Incommensurability",
      "overview": "Drawing heavily on the Neurathian tradition (reconstructed by O'Neill), this theme posits that a rational economy cannot be governed by a single unit of account (money or labor-time). Instead, economic coordination must be 'multi-criterial,' evaluating outcomes in their natural units—tons of steel, kilowatt-hours, carbon levels, or hours of care. This approach recognizes that social values like ecological sustainability and work quality are 'incommensurable' (cannot be measured on a common scale) and 'non-compensatory' (gains in one cannot offset losses in another).",
      "key_claims": [
        "Money acts as a 'pseudo-rational' device that masks genuine uncertainty and value conflict.",
        "Economic 'efficiency' is not a neutral technical goal but one value among many that must be weighed.",
        "Calculation in kind allows for the 'composition' of disparate goals without reducing them to a single metric.",
        "The Data Matrix serves as a modern 'statistical mirror' or 'isotype' system to make these trade-offs legible."
      ],
      "philosophical_commitments": [
        "Value Pluralism: The belief that human goods are multiple and cannot be reduced to a single 'utility' or 'value' function.",
        "Anti-Reductionism: Rejection of the idea that complex social and ecological realities can be captured by price signals.",
        "Epistemic Humility: Recognition of 'structural uncertainty' regarding both facts and values."
      ],
      "argumentative_moves": [
        "Critique of 'pseudo-rationalism' (the belief that more data leads to a single 'optimal' solution).",
        "Contrast between 'single-criterion optimization' (capitalism/Stalinism) and 'multi-criterial composition'.",
        "Utilization of the 'vintage problem' to demonstrate the limits of centralized, technical planning."
      ],
      "source_documents": [
        "beyond-capitalism-1",
        "beyond-capitalism-2",
        "real-political-economy-tech"
      ],
      "representative_quotes": [
        {
          "source_work_title": "Beyond Capitalism—1",
          "source_locator": "Section 5",
          "quote": "Calculation in kind would involve evaluating economic plans both quantitatively and qualitatively, but without measuring everything in terms of a single unit."
        },
        {
          "source_work_title": "Beyond Capitalism—1",
          "source_locator": "Section 5",
          "quote": "Money... creates the illusion that all outcomes can be rendered commensurate through a single unit of account, masking the presence of genuine uncertainty about both facts and values."
        }
      ],
      "centrality": "core"
    },
    {
      "theme_name": "Total Socialisation and the Investment Function",
      "overview": "This theme reimagines 'socialisation' not as the centralized state ownership of all production, but as the democratic control of the 'investment function.' Building on Neurath’s 'Total Socialisation' and Keynes's 'Socialisation of Investment,' the argument is that investment is a 'future-making' process that determines the material conditions of social life. By taking the investment function out of private hands and placing it under 'Investment Boards,' society can steer development toward social and ecological ends rather than financial returns.",
      "key_claims": [
        "Investment is the primary 'ex-ante' arena of economic coordination.",
        "A 'National Investment Board' (NIB) should act as a political assembly rather than a technocratic agency.",
        "Socialized investment decouples future production from the requirement of prior savings or anticipated profitability.",
        "The state’s role is to ensure 'full investment' to avoid the chronic stagnation and 'idleness' inherent in mature capitalism."
      ],
      "philosophical_commitments": [
        "Social Construction of the Future: The belief that technological and economic paths are not inevitable but politically chosen.",
        "Primacy of the Political: The conviction that the direction of the economy is a matter of 'collective will and knowledge' (Neurath)."
      ],
      "argumentative_moves": [
        "Synthesis of Marx’s focus on production with Keynes’s focus on the creative, forward-looking nature of investment.",
        "Critique of the 'additive theory of value' in Mill and Keynes, which fails to recognize investment as a site of strategic conflict.",
        "Distinction between 'minor improvements' (firm-level) and 'cross-sectoral transformations' (Coordinating Committees)."
      ],
      "source_documents": [
        "beyond-capitalism-1",
        "beyond-capitalism-2"
      ],
      "representative_quotes": [
        {
          "source_work_title": "Beyond Capitalism—1",
          "source_locator": "Section 8",
          "quote": "Investment is not merely the expansion of existing production lines; it is a dynamic, future-making process."
        },
        {
          "source_work_title": "Beyond Capitalism—2",
          "source_locator": "Section 6",
          "quote": "In a multi-criterial economy, investment is not guided by expected financial returns but by judgements about how to prioritize among alternative futures."
        }
      ],
      "centrality": "core"
    },
    {
      "theme_name": "Economy in Kind and the Dual-Currency Firewall",
      "overview": "To operationalize an 'economy in kind' while preserving the flexibility of markets, the framework proposes a structural break in the monetary system. This involves a digital dual-currency architecture: 'credits' for individual consumption and 'points' for inter-organizational production and investment. This 'firewall' prevents market success from translating into private capital accumulation, effectively 'de-commodifying' the power to invest and command labor.",
      "key_claims": [
        "Monetary multiplicity (separating circuits) is a historical norm that capitalism suppressed.",
        "Digital architecture can make the separation between production and consumption 'enforceable by design'.",
        "Firms should operate as non-profit, worker-run entities that 'rent' labor and land in points but pay workers in credits.",
        "The 'Points' economy removes the compulsion for 'efficiency-first' competition by eliminating the possibility of hoarding surplus."
      ],
      "philosophical_commitments": [
        "Institutional Separation: The idea that different spheres of life (consumption vs. social production) should be governed by different logics.",
        "Non-Profit Orientation: The commitment that 'purpose-driven' activity can replace 'profit-driven' activity if structural incentives are aligned."
