        "beyond-capitalism-2",
        "real-political-economy-tech"
      ],
      "representative_quotes": [
        {
          "source_work_title": "Beyond Capitalism—1",
          "source_locator": "Section 5",
          "quote": "In the presence of partial-order problems, democracy becomes not just desirable but essential."
